"""
Quick script to decode and play a base64 audio string from a request body.
Usage: python scripts/play_b64_audio.py
"""
import base64
import json
import os
import subprocess

# paste your full request body json here
REQUEST_BODY = """
{"audio_b64":"","language":"en"}
"""

_OUT_DIR = os.path.dirname(os.path.abspath(__file__))
_OUT_PATH = os.path.join(_OUT_DIR, 'test_audio.m4a')

data = json.loads(REQUEST_BODY)
b64 = data['audio_b64']

audio_bytes = base64.b64decode(b64)
with open(_OUT_PATH, 'wb') as f:
    f.write(audio_bytes)

print(f'Saved to: {_OUT_PATH} ({len(audio_bytes)} bytes)')
print('Playing...')
subprocess.run(['afplay', _OUT_PATH])
print('Done.')